#!/usr/bin/env python3
from pathlib import Path
import subprocess
import sys
import re

FILES = {
    "seed_self_state_v741.py": "\nimport json\nimport subprocess\nfrom datetime import datetime\nfrom pathlib import Path\n\nSTATE_FILE = Path(\"seed_self_state_v741.json\")\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef safe(fn, fallback=None):\n    try:\n        return fn()\n    except Exception as e:\n        return fallback if fallback is not None else {\"ok\": False, \"error\": str(e)}\n\ndef gate(mod, fn):\n    return safe(lambda: getattr(__import__(mod, fromlist=[fn]), fn)(), {\"ready\": False, \"error\": f\"{mod}.{fn} unavailable\"})\n\ndef git_head():\n    try:\n        p = subprocess.run([\"git\", \"rev-parse\", \"--short\", \"HEAD\"], capture_output=True, text=True, timeout=8)\n        return p.stdout.strip() if p.returncode == 0 else None\n    except Exception:\n        return None\n\ndef build_self_state():\n    # IMPORTANT:\n    # Do NOT call seed_v75_gate from here.\n    # v75_gate -> v75_systems -> self_state caused recursion in v75.0.0.\n    lower_gates = {\n        \"v74\": gate(\"seed_v74_gate\", \"run_v74_gate\"),\n        \"v731\": gate(\"seed_v731_gate\", \"run_v731_gate\"),\n        \"v73\": gate(\"seed_v73_gate\", \"run_v73_gate\"),\n        \"v72\": gate(\"seed_v72_gate\", \"run_v72_gate\"),\n        \"v70\": gate(\"seed_v70_gate\", \"run_v70_gate\"),\n    }\n\n    role_map, models = {}, []\n    try:\n        from seed_model_real_mode_v61 import load_role_map, list_models\n        role_map = load_role_map().get(\"role_map\", {})\n        models = list_models().get(\"models\", [])\n    except Exception:\n        pass\n\n    memory = safe(lambda: __import__(\"seed_memory_review_v75\", fromlist=[\"memory_summary\"]).memory_summary(), {})\n    avatar = safe(lambda: __import__(\"seed_avatar_panel_v74\", fromlist=[\"build_avatar_panel_state\"]).build_avatar_panel_state(), {})\n    voice = safe(lambda: __import__(\"seed_live_voice_v731\", fromlist=[\"voice_status\"]).voice_status(), {})\n\n    installed_layers_green = [\"v75\"]\n    installed_layers_green.extend([k for k, v in lower_gates.items() if v.get(\"ready\")])\n\n    data = {\n        \"created_at\": now(),\n        \"version\": \"v75.1.0\",\n        \"ok\": True,\n        \"true_current_version\": \"v75.1.0\",\n        \"previous_broken_version\": \"v75.0.0 recursion hotfixed\",\n        \"release_track\": \"Seed local companion v1-alpha hardening\",\n        \"installed_layers_green\": installed_layers_green,\n        \"gates\": {k: {\"ready\": v.get(\"ready\"), \"version\": v.get(\"version\")} for k, v in lower_gates.items()},\n        \"capabilities\": {\n            \"local_chat\": True,\n            \"ollama_model_router\": bool(role_map),\n            \"voice_record_transcribe_reply\": bool(voice.get(\"ok\")),\n            \"embodied_web_panel\": lower_gates[\"v74\"].get(\"ready\") is True,\n            \"presence_policy\": lower_gates[\"v72\"].get(\"ready\") is True,\n            \"real_memory_review\": bool(memory.get(\"ok\", True)),\n            \"self_state_truth\": True,\n            \"recursion_hotfix\": True,\n        },\n        \"models\": models,\n        \"role_map\": role_map,\n        \"memory\": memory,\n        \"avatar\": avatar,\n        \"voice\": voice,\n        \"git_head\": git_head(),\n        \"truth_rules\": [\n            \"Current version is v75.1.0 when v75.1 gate is green.\",\n            \"v75.0.0 had a recursion bug and was hotfixed.\",\n            \"v70 is an older base layer, not current.\",\n            \"Current goal is real Seed v1 hardening.\",\n            \"Mention voice/panel/memory as working when gates are green.\",\n        ],\n        \"next_recommended_updates\": [\n            \"v76 Voice 2.0\",\n            \"v77 Panel 2.0\",\n            \"v78 Proactive presence\",\n            \"v79 Permissioned executor\",\n            \"v80 Aider production loop\",\n        ],\n    }\n\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef build_seed_truth_context():\n    s = build_self_state()\n    mem = s.get(\"memory\", {})\n    return \"\\n\".join([\n        \"=== TRUE CURRENT SEED STATE OVERRIDE ===\",\n        f\"Current Seed version: {s.get('true_current_version')}\",\n        \"Current stage: moving toward real Seed v1.\",\n        f\"Green layers: {', '.join(s.get('installed_layers_green', []))}\",\n        f\"Voice working: {s['capabilities'].get('voice_record_transcribe_reply')}\",\n        f\"Embodied panel working: {s['capabilities'].get('embodied_web_panel')}\",\n        f\"Real memory review working: {s['capabilities'].get('real_memory_review')}\",\n        f\"Accepted memories: {mem.get('accepted_count', 0)}\",\n        f\"Pending memory candidates: {mem.get('pending_count', 'unknown')}\",\n        f\"Memory decisions logged: {mem.get('decision_count', 0)}\",\n        \"v70 is an older base layer, not the current version.\",\n        \"v75.0.0 recursion bug is hotfixed in v75.1.0.\",\n        \"Next best work: review memories, then v76 voice polish and v77 panel polish.\",\n        \"========================================\",\n    ])\n\ndef show_self_state():\n    print(\"\\n=== SEED v75.1 SELF-STATE TRUTH ===\")\n    print(json.dumps(build_self_state(), indent=4, ensure_ascii=False))\n\nif __name__ == \"__main__\":\n    show_self_state()\n",
    "seed_v75_systems.py": "\nimport json\nfrom datetime import datetime\nfrom pathlib import Path\n\nSTATE_FILE = Path(\"seed_v75_systems_state.json\")\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef safe(title, summary, fn):\n    try:\n        data = fn()\n        return {\"title\": title, \"summary\": summary, \"status\": \"ok\" if data.get(\"ok\", True) else \"warning\", \"data\": data}\n    except Exception as e:\n        return {\"title\": title, \"summary\": summary, \"status\": \"error\", \"error\": str(e)}\n\ndef build_v75_state():\n    # IMPORTANT:\n    # This can call self_state because self_state no longer calls v75_gate.\n    cards = [\n        safe(\"Self-State Truth\", \"Seed knows current version and green layers without recursion.\", lambda: __import__(\"seed_self_state_v741\", fromlist=[\"build_self_state\"]).build_self_state()),\n        safe(\"Real Memory Review\", \"Review/save/ignore/later accepted memory store.\", lambda: __import__(\"seed_memory_review_v75\", fromlist=[\"memory_summary\"]).memory_summary()),\n        safe(\"Embodied Companion\", \"v74 panel remains green.\", lambda: __import__(\"seed_v74_gate\", fromlist=[\"run_v74_gate\"]).run_v74_gate()),\n        safe(\"Voice Pipeline\", \"v73.1 voice remains green.\", lambda: __import__(\"seed_v731_gate\", fromlist=[\"run_v731_gate\"]).run_v731_gate()),\n    ]\n\n    data = {\n        \"created_at\": now(),\n        \"version\": \"v75.1.0\",\n        \"ok\": all(card[\"status\"] != \"error\" for card in cards),\n        \"cards\": cards,\n        \"hotfix\": \"v75.1 recursion fix\",\n    }\n\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef show_v75_status():\n    data = build_v75_state()\n    print(\"\\n=== SEED v75.1 SELF-TRUTH + REAL MEMORY STATUS ===\")\n    print(f\"OK: {data['ok']}\")\n    for card in data[\"cards\"]:\n        print(f\"- {card['title']}: {card['status']} \u2014 {card['summary']}\")\n\nif __name__ == \"__main__\":\n    show_v75_status()\n",
    "seed_v75_gate.py": "\nimport json\nimport subprocess\nfrom datetime import datetime\n\nMODULES = [\n    \"seed_self_state_v741.py\",\n    \"seed_memory_review_v75.py\",\n    \"seed_v75_systems.py\",\n    \"seed_v75_gate.py\",\n    \"seed_v75_commands.py\",\n    \"seed_natural_intent_router_v75.py\",\n]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef compile_module(module):\n    proc = subprocess.run([\"python\", \"-m\", \"py_compile\", module], capture_output=True, text=True, timeout=30)\n    return {\"module\": module, \"ok\": proc.returncode == 0, \"stderr\": proc.stderr[-1600:]}\n\ndef run_v75_gate():\n    checks = [compile_module(m) for m in MODULES]\n    modules_ok = all(c[\"ok\"] for c in checks)\n    details = {}\n\n    try:\n        from seed_v75_systems import build_v75_state\n        state = build_v75_state()\n        systems_ok = state.get(\"ok\") is True and len(state.get(\"cards\", [])) >= 4\n        details[\"v75_state\"] = {\"ok\": state.get(\"ok\"), \"cards\": len(state.get(\"cards\", [])), \"version\": state.get(\"version\")}\n    except Exception as e:\n        systems_ok = False\n        details[\"v75_state_error\"] = str(e)\n\n    try:\n        from seed_v74_gate import run_v74_gate\n        v74 = run_v74_gate()\n        v74_ok = v74.get(\"ready\") is True\n        details[\"v74\"] = {\"ready\": v74.get(\"ready\")}\n    except Exception as e:\n        v74_ok = False\n        details[\"v74_error\"] = str(e)\n\n    try:\n        from seed_self_state_v741 import build_self_state\n        s = build_self_state()\n        truth_ok = s.get(\"true_current_version\") == \"v75.1.0\" and s.get(\"capabilities\", {}).get(\"recursion_hotfix\") is True\n        details[\"truth\"] = {\"current\": s.get(\"true_current_version\"), \"green_layers\": s.get(\"installed_layers_green\", [])}\n    except Exception as e:\n        truth_ok = False\n        details[\"truth_error\"] = str(e)\n\n    report = {\n        \"created_at\": now(),\n        \"version\": \"v75.1.0\",\n        \"ready\": modules_ok and systems_ok and v74_ok and truth_ok,\n        \"modules_ok\": modules_ok,\n        \"systems_ok\": systems_ok,\n        \"v74_ok\": v74_ok,\n        \"truth_ok\": truth_ok,\n        \"module_checks\": checks,\n        \"details\": details,\n        \"hotfix\": \"Removed v75_gate call from self_state to stop recursion.\",\n    }\n\n    with open(\"seed_v75_gate_report.json\", \"w\") as f:\n        json.dump(report, f, indent=4)\n\n    return report\n\ndef show_v75_gate():\n    report = run_v75_gate()\n    print(\"\\n=== SEED v75.1 SELF-TRUTH + REAL MEMORY GATE ===\")\n    print(f\"Ready: {report['ready']}\")\n    print(f\"Modules OK: {report['modules_ok']}\")\n    print(f\"Systems OK: {report['systems_ok']}\")\n    print(f\"v74 OK: {report['v74_ok']}\")\n    print(f\"Truth OK: {report['truth_ok']}\")\n    print(f\"Details: {report['details']}\")\n\nif __name__ == \"__main__\":\n    show_v75_gate()\n",
}

for path, text in FILES.items():
    Path(path).write_text(text.strip() + "\n")
    print("Wrote", path)

# Update config version flag.
p = Path("seed_config.py")
text = p.read_text(errors="ignore") if p.exists() else 'SEED_VERSION = "v75.1.0"\n'
text = re.sub(r'^SEED_VERSION\s*=\s*".*?"', 'SEED_VERSION = "v75.1.0"', text, flags=re.M)
if "SEED_V751_RECURSION_HOTFIX" not in text:
    text += '\nSEED_V751_RECURSION_HOTFIX = True\n'
p.write_text(text)
print("Updated seed_config.py")

# Docs
p = Path("Seed_Core.md")
text = p.read_text(errors="ignore") if p.exists() else ""
if "Seed v75.1 — Recursion Hotfix" not in text:
    text += """
## Seed v75.1 — Recursion Hotfix

Fixes v75.0.0 recursive gate loop:
self_state -> v75_gate -> v75_systems -> self_state.

Self-state no longer calls v75_gate. It treats v75.1 as the current layer and checks lower green layers only.
"""
p.write_text(text)
print("Updated Seed_Core.md")

# Compile checks.
checks = [
    "seed_self_state_v741.py",
    "seed_v75_systems.py",
    "seed_v75_gate.py",
    "seed_memory_review_v75.py",
    "seed_commands.py",
]
for m in checks:
    if Path(m).exists():
        proc = subprocess.run(["python", "-m", "py_compile", m], capture_output=True, text=True, timeout=30)
        print("$ python -m py_compile", m)
        if proc.returncode == 0:
            print("OK")
        else:
            print(proc.stderr)
            sys.exit(proc.returncode)

print("\nSeed v75.1 recursion hotfix installed.")
